// ===== DEBOUNCE =====
var lastAlertTime = global.get('fallLastAlertTime') || 0;
var now = Date.now();
var COOLDOWN = 60 * 1000; // 60 giay

if (lastAlertTime !== 0 && (now - lastAlertTime) < COOLDOWN) {
    return null; // dang cooldown, chan
}

global.set('fallLastAlertTime', now); // Cap nhat moc thoi gian moi

// ===== PHAN LOAI + TIMESTAMP =====
msg.topic = "fall";
msg.eventTime = new Date().toISOString();

if (msg.payload && msg.payload.image_path) {
    msg.filename = msg.payload.image_path;
} else {
    // TODO: cap nhat duong dan anh du phong phu hop voi may thuc te khi trien khai
    msg.filename = "/opt/smart-home/assets/fallback_fall.jpg";
}

// Lenh gui thang cho ESP32 (topic home/esp32/alarm) de bat coi.
// LUU Y: node 'file in' phia sau se GHI DE msg.payload bang du lieu anh,
// nen gia tri nay chi thuc su duoc dung boi nhanh mqtt out (function1 -> mqtt out),
// con nhanh Telegram se lay du lieu anh tu file in / function 2.
msg.payload = "FALL_ALARM_ON";
return msg;

if (msg.error) {
    // Khong doc duoc anh (VD: AI chua kip luu file, sai duong dan...)
    // Van phai gui canh bao, chi la khong kem anh, tranh mat canh bao khan cap.
    msg.payload = {
        chatId: "8823676499",
        type: "message",
        content: "CANH BAO TE NGA KHAN CAP! (Khong lay duoc anh hien truong)"
    };
} else {
    var imageBuffer = msg.payload;
    msg.payload = {
        chatId: "8823676499",
        type: "photo",
        content: imageBuffer,
        caption: "CANH BAO TE NGA KHAN CAP!"
    };
}
return msg;

msg.topic = "gas";
msg.eventTime = new Date().toISOString();
msg.payload = {
    chatId: "8823676499",
    type: "message",
    content: "🚨 CẢNH BÁO KHẨN CẤP: Đã phát hiện rò rỉ khí gas lúc " + new Date().toLocaleTimeString('vi-VN')
};
return msg;

msg.topic = "home/esp32/alarm";
msg.eventTime = new Date().toISOString();
msg.payload = "GAS_ALARM_ON";
return msg;

// 1. Khởi tạo biến toàn cục chống spam cho luồng DHT22
if (typeof global.dhtLastAlertTime === 'undefined') {
    global.dhtLastAlertTime = 0;
}

var now = Date.now();
var COOLDOWN = 60 * 1000; // 60 giây cooldown giữa các lần báo động DHT
var diff = now - global.dhtLastAlertTime;


// 2. Kiểm tra điều kiện ngưỡng cảm biến như cũ
const data = msg.payload;
const temp = data.temp;
const humidity = data.humidity;

const TEMP_HIGH = 35;
const TEMP_LOW = 16;
const HUMID_HIGH = 85;

let alert = null;

if (temp >= TEMP_HIGH) {
    alert = `⚠️ Nhiệt độ quá cao: ${temp}°C. Kiểm tra điều hòa/quạt cho người già.`;
} else if (temp <= TEMP_LOW) {
    alert = `⚠️ Nhiệt độ quá thấp: ${temp}°C. Cần giữ ấm cho người già.`;
} else if (humidity >= HUMID_HIGH) {
    alert = `⚠️ Độ ẩm cao bất thường: ${humidity}%.`;
}

// 3. Nếu có cảnh báo VÀ đã qua thời gian cooldown thì mới cho đi
if (alert) {
    if (global.dhtLastAlertTime === 0 || diff >= COOLDOWN) {
        global.dhtLastAlertTime = now; // Cập nhật mốc thời gian mới

        msg.topic = "dht22";
        msg.eventTime = new Date().toISOString();
        msg.payload = {
            chatId: "8823676499",
            type: "message",
            content: alert
        };
        return msg;
    } else {
        // Đang trong thời gian cooldown -> Chặn lại không gửi Telegram dồn dập
        return null;
    }
}

return null;

var lastAlertTime = global.get('fallLastAlertTime') || 0;
var now = Date.now();



if (lastAlertTime === 0 || (now - lastAlertTime) > 5 * 60 * 1000) {

    return null;
}

global.set('fallLastAlertTime', 0); // reset lại


var alarmMsg = { topic: "home/esp32/alarm", payload: "ALARM_OFF" };
var telegramMsg = {
    payload: {
        chatId: "8823676499",
        type: "message",
        content: "✅ Đã xác nhận an toàn. Báo động té ngã tự hủy."
    }
};
return [alarmMsg, telegramMsg];

// Khoi tao bien toan cuc luu moc thoi gian lan chay truoc (neu chua co)
if (typeof global.gasLastAlertTime === 'undefined') {
    global.gasLastAlertTime = 0;
}

var now = Date.now();
var COOLDOWN = 60 * 1000; // 60 giay
var diff = now - global.gasLastAlertTime;

node.warn("Gas Gate check - diff: " + diff + "ms (cooldown=" + COOLDOWN + "ms)");

// Neu la lan dau tien hoac da qua thoi gian cooldown
if (global.gasLastAlertTime === 0 || diff >= COOLDOWN) {
    global.gasLastAlertTime = now; // Cap nhat moc thoi gian moi
    msg.topic = "gas";
    msg.eventTime = new Date().toISOString();
    // Phai tra ve MANG de ca 2 output cung chay:
    // output 1 -> function 3 (Telegram), output 2 -> function 4 (bat coi ESP32)
    return [msg, msg];
} else {
    return null; // Chan lai vi dang trong thoi gian cooldown
}

global.set('fallLastAlertTime', 0);
global.set('gasLastAlertTime', 0);
global.set('dhtLastAlertTime', 0);

msg.topic = "home/esp32/alarm";
msg.payload = "ALARM_OFF";
return msg;
